-- Table structure for table `temporada_jugadores`
--

DROP TABLE IF EXISTS `temporada_jugadores`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `temporada_jugadores` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `temporada_id` int(11) NOT NULL,
  `jugador_id` int(11) NOT NULL,
  `posicion_natural` varchar(10) NOT NULL,
  `posiciones_secundarias` varchar(50) NOT NULL DEFAULT '',
  `ovr_base` int(11) NOT NULL,
  `es_estrella` tinyint(1) NOT NULL DEFAULT 0,
  `es_mvp` tinyint(1) NOT NULL DEFAULT 0,
  `dorsal` int(11) DEFAULT NULL COMMENT 'Pendiente: completar vía API lahistoriariver.com',
  `foto_epoca` varchar(255) DEFAULT NULL COMMENT 'Foto de ESE año (scripts/enriquecer_epoca.php)',
  `foto_fuente` varchar(255) DEFAULT NULL COMMENT 'Título del archivo en Commons (auditoría)',
  `foto_anio` int(11) DEFAULT NULL COMMENT 'Año real de la foto (puede diferir ±1 del anio_orden)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `temporada_id` (`temporada_id`,`jugador_id`),
  KEY `jugador_id` (`jugador_id`),
  CONSTRAINT `temporada_jugadores_ibfk_1` FOREIGN KEY (`temporada_id`) REFERENCES `temporadas` (`id`),
  CONSTRAINT `temporada_jugadores_ibfk_2` FOREIGN KEY (`jugador_id`) REFERENCES `jugadores` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5512 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

