--
-- Table structure for table `temporadas`
--

DROP TABLE IF EXISTS `temporadas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `temporadas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `club_id` int(11) NOT NULL,
  `anio_orden` int(11) NOT NULL,
  `etiqueta` varchar(80) NOT NULL,
  `formacion` varchar(20) NOT NULL,
  `ovr_equipo` int(11) DEFAULT NULL,
  `escudo_epoca` varchar(255) DEFAULT NULL COMMENT 'Escudo de ESE año (stretch Tanda 1)',
  `campeon` tinyint(1) NOT NULL DEFAULT 0,
  `tecnico_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_temp_club_etiqueta` (`club_id`,`etiqueta`),
  KEY `tecnico_id` (`tecnico_id`),
  CONSTRAINT `temporadas_ibfk_1` FOREIGN KEY (`club_id`) REFERENCES `clubes` (`id`),
  CONSTRAINT `temporadas_ibfk_2` FOREIGN KEY (`tecnico_id`) REFERENCES `tecnicos` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=502 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `temporadas`
--

LOCK TABLES `temporadas` WRITE;
/*!40000 ALTER TABLE `temporadas` DISABLE KEYS */;
