DROP TABLE IF EXISTS `torneo_equipos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `torneo_equipos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `torneo_id` int(11) NOT NULL,
  `temporada_id` int(11) DEFAULT NULL,
  `zona` varchar(2) DEFAULT NULL COMMENT 'A/B en liga30, A-H en copa, NULL en premier',
  `es_usuario` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_torneo_temp` (`torneo_id`,`temporada_id`),
  KEY `temporada_id` (`temporada_id`),
  CONSTRAINT `torneo_equipos_ibfk_1` FOREIGN KEY (`torneo_id`) REFERENCES `torneos` (`id`),
  CONSTRAINT `torneo_equipos_ibfk_2` FOREIGN KEY (`temporada_id`) REFERENCES `temporadas` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=429 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

